from pathlib import Path
import json,html
p=Path('/workspace/cc-practice/地图规划/地面底图R3');d=json.loads((p/'地面底图数据.json').read_text());B={b['id']:b for b in d['buildings']}
A={'D09','G26','G50'};Bs={'G21','G22','G23','G17','G10','G43','G44','D02','D08','D10','D07','D12','G48'}
pts=lambda v:' '.join(','.join(str(round(n,2)) for n in x) for x in v)
def path(poly):return 'M'+'L'.join(','.join(str(round(n,2)) for n in a) for a in poly)+'Z'
s=['<svg id="map" xmlns="http://www.w3.org/2000/svg" viewBox="125 160 1885 925" aria-label="全校道路及建筑占地底图"><defs><pattern id="hatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="7" height="7" fill="#e0e4df"/><path d="M0 0V7" stroke="#b8c2b9" stroke-width="1.4"/></pattern></defs><rect x="0" y="0" width="2100" height="1200" fill="#e9eeeb"/>']
for c in d['campuses']:s.append(f'<path d="{path(c["polygon"])}" fill="#ced9ce" stroke="#9baa9b" stroke-width="1.5"/>')
for ex in d['exclusions']:s.append(f'<path d="{path(ex["polygon"])}" fill="url(#hatch)" stroke="#b0bcb0"/>')
for z in d['spaces']:
 color='#b4cbaa' if z['kind']=='green' else '#a9cbd3' if z['kind']=='water' else '#d2c8b6' if z['kind']=='track' else '#c1ceb9'
 s.append(f'<path d="{path(z["polygon"])}" fill="{color}" stroke="#abbca8" stroke-width=".7"/>')
for f in d['forecourts']:s.append(f'<path d="{path(f["polygon"])}" fill="#e8e3d3" stroke="#cbc4b1" stroke-width=".8"/>')
for r in d['roads']+d['connections']:
 s.append(f'<polyline data-road="{r["id"]}" points="{pts(r["points"])}" fill="none" stroke="#ffffff" stroke-width="{r["width"]}" stroke-linecap="round" stroke-linejoin="round"><title>{r["name"]}</title></polyline>')
for b in d['buildings']:
 tier='A' if b['id'] in A else 'B' if b['id'] in Bs else 'C'
 shape=path(b['polygon'])+''.join(path(h) for h in b.get('holes',[]))+''.join(path(a['polygon']) for a in b.get('additionalFootprints',[]))
 s.append(f'<path class="building tier{tier}" data-building="{b["id"]}" tabindex="0" d="{shape}" fill-rule="evenodd" fill="#9fa9a4" stroke="#64776c" stroke-width="1" aria-label="{html.escape(b["name"])}"><title>{html.escape(b["name"])}</title></path>')
# Elevated passages use fine outlines only; white ground remains visible below.
for c in d['structuralPassages']:s.append(f'<polyline points="{pts(c["points"])}" fill="none" stroke="#778a80" stroke-width="4" stroke-dasharray="1 3"><title>{c["name"]}</title></polyline>')
s.append('<g class="grade-only" style="display:none"><rect x="1235" y="491" width="286" height="69" rx="5" fill="none" stroke="#c26a4c" stroke-width="2" stroke-dasharray="6 4"/><text x="1378" y="582" font-size="11" text-anchor="middle" fill="#8a4c38" paint-order="stroke" stroke="#f7f9f3" stroke-width="3">宿舍组：仅原功能入口按A级精做</text></g>')
s.append('<g id="labels" fill="#263f34" font-size="11" font-weight="550" text-anchor="middle" paint-order="stroke" stroke="#eef3eb" stroke-width="2.5" stroke-linejoin="round">')
names={'W01':'会计学院','W03':'创业中心','W04':'体育馆／游泳池','W05':'学术交流中心','W06':'图书馆','W07':'风雨操场','W08':'第四教学楼','W09':'羽毛球馆','W10':'经济学院','W12':'第四食堂','G01':'27号楼','G02':'20号楼','G03':'十一宿舍','G09':'19号楼','G10':'第三食堂','G17':'新体育馆','G18':'行政大楼','G19':'教技中心','G20':'教技中心','G21':'第二教学楼','G22':'第一教学楼','G23':'国定梯教','G24':'法学院','G25':'浴室／理发室','G26':'第一食堂','G27':'研究生院','G28':'六宿舍','G29':'五宿舍','G30':'北四','G31':'南四','G32':'北三','G33':'南三','G34':'二宿舍','G35':'一宿舍','G36':'校史馆','G37':'育衡','G38':'档案馆','G39':'红瓦楼','G40':'学生艺术中心','G41':'第二食堂','G42':'医疗服务','G43':'科研楼','G44':'科研裙房','G45':'宁远B','G47':'宁远A','G48':'学生中心','D01':'教师发展中心','D02':'金融学院','D03':'院楼','D04':'同新楼','D05':'人文学院','D06':'商学院','D07':'统计院楼','D08':'武东梯教','D09':'第三教学楼','D10':'信管','D11':'教务处','D12':'统计院楼','D16':'保卫处'}
for id,name in names.items():
 b=B[id];poly=b['polygon'];cx=sum(x for x,y in poly)/len(poly);cy=sum(y for x,y in poly)/len(poly)
 if id=='G09':cx,cy=966,425
 if id=='W06':cx,cy=649,742
 if id=='G37':cx,cy=1588,520
 if id=='G32':cx,cy=1394,504
 if id=='G30':cx,cy=1284,504
 if id=='G36':cx,cy=1550,496
 if id=='D10':cx,cy=1104,955
 s.append(f'<text x="{cx:.2f}" y="{cy+4:.2f}">{name}</text>')
s.append('</g>')
# Location callout stays off the street network.
s.append('<g id="cainiao-callout"><path d="M1839 625L1885 668L1885 690L1640 690" fill="none" stroke="#356c7e" stroke-width="1.8"/><circle cx="1839" cy="625" r="4" fill="#356c7e"/><text x="1640" y="715" fill="#275c70" font-size="19" font-weight="700">菜鸟驿站 · 快递中心</text><text x="1640" y="736" fill="#4c6d73" font-size="11">独立占地 · 校内侧接入前场</text></g>')
s.append('<g font-size="20" fill="#4b6458" font-weight="600"><text x="360" y="352">武川片区</text><text x="1030" y="208">国定片区</text><text x="825" y="1015">武东片区</text></g>')
for e in d['gates']:
 s.append(f'<circle cx="{e["x"]}" cy="{e["y"]}" r="4" fill="#486f5c" stroke="white" stroke-width="1.5"/><text class="gate-label" x="{e["x"]}" y="{e["y"]-12}" fill="#3d5a4b" font-size="11" text-anchor="middle" paint-order="stroke" stroke="#eff3ed" stroke-width="3">{e["name"]}</text>')
s.append('<g fill="#3a5c4d"><path d="M235 275 L244 238 L253 275 L244 267Z"/><text x="244" y="226" font-size="19" text-anchor="middle">N</text></g></svg>')
svg=''.join(s);(p/'全校道路占地.svg').write_text(svg)
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>财大校园 · 道路与占地底图</title><style>*{box-sizing:border-box}body{margin:0;background:#e9eeeb;color:#284438;font:15px 'Noto Sans CJK SC','Microsoft YaHei',sans-serif}header{height:92px;background:#f8faf7;padding:18px 28px;border-bottom:1px solid #c8d4c9;display:flex;justify-content:space-between;align-items:center}h1{margin:0;font-size:25px;letter-spacing:.5px}header p{margin:5px 0 0;color:#647a6a;font-size:13px}nav{display:flex;gap:8px;flex-wrap:wrap}button{cursor:pointer;border:1px solid #b4c6b6;background:#f9fcf8;color:#3b5c47;padding:9px 14px;border-radius:5px;font:inherit}button.active{background:#426b55;color:white;border-color:#426b55}main{height:calc(100vh - 158px);position:relative;overflow:hidden;min-height:440px}svg{width:100%;height:100%;display:block;touch-action:none;cursor:grab}svg:active{cursor:grabbing}.building{cursor:pointer;transition:fill .15s}.building:hover,.building:focus{fill:#c5d8c1;stroke:#315d45;stroke-width:2;outline:none}.grades .grade-only{display:inline!important}.grades .tierA{fill:#df9479}.grades .tierB{fill:#c7b37c}.hidden-labels #labels,.hidden-labels .gate-label{display:none}footer{height:66px;display:flex;justify-content:space-between;align-items:center;padding:0 28px;border-top:1px solid #cad5ca;background:#f8faf7;font-size:13px}.legend{display:flex;gap:19px;align-items:center}.swatch{display:inline-block;width:20px;height:12px;border:1px solid #b5c3b5;margin-right:6px;vertical-align:middle}.hint{color:#6d8172}#detail{position:absolute;bottom:16px;left:22px;padding:12px 16px;background:#ffffffed;border:1px solid #b7cab9;border-radius:6px;max-width:500px;display:none;pointer-events:none;font-size:14px}#detail b{display:block;margin-bottom:4px}#gradeLegend{display:none}.grades #gradeLegend{display:inline}.corner{position:absolute;right:20px;top:15px;color:#526f5c;font-size:12px;background:#f9fcf5d9;padding:7px 10px;border-radius:5px}@media(max-width:1000px){header{height:126px;display:block;padding:12px}nav{margin-top:10px}h1{font-size:21px}button{font-size:12px;padding:5px 8px}main{height:calc(100vh - 204px)}footer{height:78px;padding:10px;font-size:11px}.hint{display:none}}</style><header><div><h1>上海财经大学 · 道路与建筑占地</h1><p>第一阶段地面底图 · 北向朝上 · 院落与建筑分开表达</p></div><nav><button data-view="all" class="active">全校</button><button data-view="east">右侧放大</button><button data-view="south">武东</button><button data-view="west">武川</button><button id="names">名称 开 / 关</button><button id="grades">制作分级</button></nav></header><main>'''+svg+'''<div class="corner" id="corner">全校道路与建筑占地</div><div id="detail"></div></main><footer><div class="legend"><span><i class="swatch" style="background:white"></i>道路</span><span><i class="swatch" style="background:#9fa9a4"></i>楼体占地</span><span><i class="swatch" style="background:#e8e3d3"></i>内院 / 前场</span><span><i class="swatch" style="background:#b4cbaa"></i>绿地</span><span id="gradeLegend">橙 A · 金 B · 灰 C</span></div><span class="hint">拖动平移 · 滚轮缩放 · 点击楼块查看名称</span></footer><script>
const DATA='''+json.dumps(d,ensure_ascii=False)+''';
const map=document.querySelector('#map'),detail=document.querySelector('#detail');const views={all:[125,160,1885,925],east:[890,216,1035,550],south:[735,570,575,510],west:[150,310,750,555]};let box=[...views.all],drag=null;function draw(){map.setAttribute('viewBox',box.join(' '))}function fit(v){box=[...views[v]];draw();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.querySelector('#corner').textContent={all:'全校道路与建筑占地',east:'右侧主路与快递中心',south:'武东片区',west:'武川片区'}[v];detail.style.display='none'}window.fit=fit;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>fit(b.dataset.view));document.querySelector('#names').onclick=()=>document.body.classList.toggle('hidden-labels');document.querySelector('#grades').onclick=()=>document.body.classList.toggle('grades');
function world(e){const p=map.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(map.getScreenCTM().inverse())}
map.addEventListener('wheel',e=>{e.preventDefault();const p=world(e),k=e.deltaY>0?1.14:.877;if(box[2]*k<160||box[2]*k>2600)return;box=[p.x-(p.x-box[0])*k,p.y-(p.y-box[1])*k,box[2]*k,box[3]*k];draw()},{passive:false});map.addEventListener('pointerdown',e=>{drag={p:world(e),box:[...box],start:[e.clientX,e.clientY]};map.setPointerCapture(e.pointerId)});map.addEventListener('pointermove',e=>{if(!drag)return;const p=world(e);box[0]+=drag.p.x-p.x;box[1]+=drag.p.y-p.y;draw()});map.addEventListener('pointerup',e=>{if(drag&&Math.hypot(e.clientX-drag.start[0],e.clientY-drag.start[1])<5){const t=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-building]');if(t){const b=DATA.buildings.find(x=>x.id===t.dataset.building);detail.replaceChildren();const title=document.createElement('b');title.textContent=b.name;detail.append(title,document.createTextNode(b.id==='G50'?'独立快递中心占地，保留菜鸟场景入口；白色道路接入校内侧前场。':b.holes?'楼体与内部庭院分开；院落留空。':'灰色表示楼体占地，白色表示道路；建筑外观在后续阶段制作。'));detail.style.display='block'}}drag=null});map.addEventListener('pointercancel',()=>drag=null);
</script></html>'''
(p/'打开地面底图.html').write_text(page)
print('SVG + self-contained interactive viewer saved')
